//go:build linux || android

package carrier

// Drain-completeness tests on a real kernel. They use only the queue's public
// API (NewSocketErrorQueue, Drain, Stats) plus read-only socket inspection, so
// they also compile against the Round D v2 tree, where the backlog test is RED.
//
// Accounting is exact. The ICMP errors are generated by the client netns l4c,
// whose ICMP rate limits the harness disables (icmp_ratelimit=0,
// icmp_msgs_per_sec and icmp_msgs_burst raised), and the test reads the number
// generated from l4c's own Icmp OutDestUnreachs counter. The gateway socket's
// receive buffer is sized so no error record is refused.

import (
	"strconv"
	"strings"
	"sync"
	"testing"
	"time"
	"unsafe"

	"net/netip"

	"golang.org/x/sys/unix"
)

// l4ClientOutDestUnreachs reads Icmp OutDestUnreachs in the client netns.
func l4ClientOutDestUnreachs(t *testing.T) uint64 {
	t.Helper()
	out := l4Sh(t, "ip", "netns", "exec", "l4c", "cat", "/proc/net/snmp")
	var hdr []string
	for _, line := range strings.Split(out, "\n") {
		if !strings.HasPrefix(line, "Icmp: ") {
			continue
		}
		fs := strings.Fields(line)
		if hdr == nil {
			hdr = fs
			continue
		}
		for i, h := range hdr {
			if h == "OutDestUnreachs" && i < len(fs) {
				n, _ := strconv.ParseUint(fs[i], 10, 64)
				return n
			}
		}
	}
	t.Fatal("no Icmp OutDestUnreachs in l4c /proc/net/snmp")
	return 0
}

// rmemAlloc is SO_MEMINFO's receive allocation: error-queue records are
// charged to it (sock_queue_err_skb), so it is zero once the queue is empty and
// no datagram is waiting. Reading it drains nothing.
func rmemAlloc(t *testing.T, fd int) (alloc, rcvbuf uint32) {
	t.Helper()
	var mi [unix.SK_MEMINFO_VARS]uint32
	l := uint32(len(mi) * 4)
	if _, _, e := unix.Syscall6(unix.SYS_GETSOCKOPT, uintptr(fd), unix.SOL_SOCKET, unix.SO_MEMINFO,
		uintptr(unsafe.Pointer(&mi[0])), uintptr(unsafe.Pointer(&l)), 0); e != 0 {
		t.Fatalf("SO_MEMINFO: %v", e)
	}
	return mi[unix.SK_MEMINFO_RMEM_ALLOC], mi[unix.SK_MEMINFO_RCVBUF]
}

func l4ErrqGateway(t *testing.T) (*SocketErrorQueue, int) {
	t.Helper()
	l4Qdisc(t, "pfifo", "limit", "5000")
	gw := l4UDP(t, "l4g", netip.AddrPortFrom(l4Gateway, 0))
	if err := gw.SetReadBuffer(64 << 20); err != nil {
		t.Fatal(err)
	}
	if _, err := EnableSendErrorReporting(gw); err != nil {
		t.Fatal(err)
	}
	q, err := NewSocketErrorQueue(gw)
	if err != nil {
		t.Fatal(err)
	}
	return q, fdOf(t, gw)
}

// queueICMP sends to the closed client port until l4c has generated at least
// want port unreachables, and returns the exact number generated.
func queueICMP(t *testing.T, fd int, want uint64) uint64 {
	t.Helper()
	sa := &unix.SockaddrInet4{Port: int(l4ClosedClientPort.Port()), Addr: l4ClosedClientPort.Addr().As4()}
	base := l4ClientOutDestUnreachs(t)
	for sent := 0; ; sent++ {
		_ = unix.Sendto(fd, []byte("x"), unix.MSG_DONTWAIT, sa)
		time.Sleep(100 * time.Microsecond)
		if sent%200 == 199 && l4ClientOutDestUnreachs(t)-base >= want {
			break
		}
		if sent > int(want)*6+1000 {
			t.Fatalf("l4c generated only %d port unreachables after %d sends", l4ClientOutDestUnreachs(t)-base, sent)
		}
	}
	time.Sleep(200 * time.Millisecond)
	return l4ClientOutDestUnreachs(t) - base
}

// waitDrained polls, read-only, until Drained reaches want and the receive
// allocation is zero, or the timeout passes.
func waitDrained(t *testing.T, q *SocketErrorQueue, fd int, want uint64, timeout time.Duration) (uint64, uint32) {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for {
		d := q.Stats().Drained
		alloc, _ := rmemAlloc(t, fd)
		if (d >= want && alloc == 0) || time.Now().After(deadline) {
			return d, alloc
		}
		time.Sleep(20 * time.Millisecond)
	}
}

// TestNetnsABacklogBeyondTheDrainCapEmptiesWithNoFurtherTraffic queues more
// than 4096 records, requests ONE drain, then sends nothing and drains nothing
// more. The queue must still empty completely: work beyond one attempt's cap
// must be continued, not dropped. RED on v2, which stopped at 4096.
func TestNetnsABacklogBeyondTheDrainCapEmptiesWithNoFurtherTraffic(t *testing.T) {
	requireL4Netns(t)
	q, fd := l4ErrqGateway(t)
	generated := queueICMP(t, fd, 5000)
	alloc0, rcvbuf := rmemAlloc(t, fd)
	t.Logf("generated=%d rmem_alloc=%d rcvbuf=%d before the drain", generated, alloc0, rcvbuf)
	if generated <= 4096 {
		t.Fatalf("setup queued only %d records; need more than 4096", generated)
	}
	first := q.Drain()
	drained, alloc := waitDrained(t, q, fd, generated, 5*time.Second)
	t.Logf("first Drain call read %d; eventually drained=%d of %d, rmem_alloc=%d stats=%+v",
		first, drained, generated, alloc, q.Stats())
	if drained != generated || alloc != 0 {
		t.Fatalf("drained %d of %d records (rmem_alloc %d) with no further traffic: the work past the cap was abandoned",
			drained, generated, alloc)
	}
}

// TestNetnsConcurrentDrainAccountsExactly: drains race each other while errors
// arrive, then a synchronized final burst of requests runs once after the
// traffic stops. There are no rescue drains. Every generated record must be
// drained exactly once and the queue must end empty.
func TestNetnsConcurrentDrainAccountsExactly(t *testing.T) {
	requireL4Netns(t)
	q, fd := l4ErrqGateway(t)
	sa := &unix.SockaddrInet4{Port: int(l4ClosedClientPort.Port()), Addr: l4ClosedClientPort.Addr().As4()}
	base := l4ClientOutDestUnreachs(t)

	stop := make(chan struct{})
	var wg sync.WaitGroup
	for i := 0; i < 8; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				select {
				case <-stop:
					return
				default:
				}
				q.Drain()
				time.Sleep(200 * time.Microsecond)
			}
		}()
	}
	deadline := time.Now().Add(1500 * time.Millisecond)
	for time.Now().Before(deadline) {
		_ = unix.Sendto(fd, []byte("x"), unix.MSG_DONTWAIT, sa)
		time.Sleep(150 * time.Microsecond)
	}
	close(stop)
	wg.Wait()
	time.Sleep(200 * time.Millisecond) // the last ICMP replies land
	generated := l4ClientOutDestUnreachs(t) - base

	// One synchronized burst of 8 requests, then nothing.
	start := make(chan struct{})
	var burst sync.WaitGroup
	for i := 0; i < 8; i++ {
		burst.Add(1)
		go func() {
			defer burst.Done()
			<-start
			q.Drain()
		}()
	}
	close(start)
	burst.Wait()

	drained, alloc := waitDrained(t, q, fd, generated, 3*time.Second)
	st := q.Stats()
	t.Logf("generated=%d drained=%d rmem_alloc=%d stats=%+v", generated, drained, alloc, st)
	if generated == 0 {
		t.Fatal("no ICMP generated; the test did not exercise the drain")
	}
	if drained != generated || alloc != 0 {
		t.Fatalf("drained %d of %d generated records (rmem_alloc %d): a request was lost or a record left behind",
			drained, generated, alloc)
	}
	if st.DrainFailures != 0 {
		t.Fatalf("clean concurrent drains recorded failures: %+v", st)
	}
	if st.DrainSkipped == 0 {
		t.Fatal("no request was ever skipped; the test did not exercise contention")
	}
	if l4ClientOutDestUnreachs(t)-base != generated {
		t.Fatal("ICMP was still being generated after the traffic stopped")
	}
}
